import { test } from '@playwright/test';
import { witness } from '@testivai/witness-playwright';

// Each page against its approved baseline, at every size in the config.
const PAGES = [
  ['home', '/'],
  ['products', '/products.html'],
  ['pricing', '/pricing.html'],
  ['orders', '/orders.html'],
  ['contact', '/contact.html'],
  ['about', '/about.html'],
];

for (const [name, url] of PAGES) {
  test(name, async ({ page }, testInfo) => {
    await page.goto(url);
    await witness(page, testInfo, name);
  });
}
// Serves site/ on http://127.0.0.1:4173 (or $PORT). No dependencies.
const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');

const root = path.join(__dirname, 'site');
const port = Number(process.env.PORT || 4173);

const types = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.woff2': 'font/woff2',
  '.txt': 'text/plain; charset=utf-8',
};

function resolve(urlPath) {
  const rel = path.posix.normalize('/' + decodeURIComponent(urlPath.split('?')[0]));
  let file = path.join(root, rel);
  if (!file.startsWith(root)) return null;
  if (fs.existsSync(file) && fs.statSync(file).isDirectory()) file = path.join(file, 'index.html');
  return fs.existsSync(file) ? file : null;
}

http
  .createServer((req, res) => {
    let file = null;
    try {
      file = resolve(req.url);
    } catch {
      file = null;
    }
    if (!file) {
      res.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
      res.end('Not found');
      return;
    }
    res.writeHead(200, {
      'content-type': types[path.extname(file)] || 'application/octet-stream',
      'cache-control': 'no-store',
    });
    fs.createReadStream(file).pipe(res);
  })
  .listen(port, '127.0.0.1', () => {
    console.log(`Acme Storefront on http://127.0.0.1:${port}`);
  });

