const T=JSON.parse(require("fs").readFileSync(process.env.TMPDIR+"/tables.json"));
const B=k=>Buffer.from(T[k],"base64");
const cmap=B("cmap"), hmtx=B("hmtx"), head=B("head");
console.log("upm",head.readUInt16BE(18));
const n=cmap.readUInt16BE(2); let sub;
for(let i=0;i<n;i++){const pid=cmap.readUInt16BE(4+i*8),eid=cmap.readUInt16BE(6+i*8),off=cmap.readUInt32BE(8+i*8);const fmt=cmap.readUInt16BE(off);if(pid===3&&eid===1&&fmt===4)sub=off}
const segX2=cmap.readUInt16BE(sub+6);const ends=sub+14,starts=ends+segX2+2,deltas=starts+segX2,ros=deltas+segX2;
function gid(c){for(let i=0;i<segX2/2;i++){const e=cmap.readUInt16BE(ends+i*2);if(c<=e){const s=cmap.readUInt16BE(starts+i*2);if(c<s)return 0;const d=cmap.readInt16BE(deltas+i*2),ro=cmap.readUInt16BE(ros+i*2);if(!ro)return (c+d)&0xffff;const g=cmap.readUInt16BE(ros+i*2+ro+(c-s)*2);return g?(g+d)&0xffff:0}}return 0}
const out=[];
for(const ch of " 0123456789.,ADOWYaeorstuy "){const g=gid(ch.charCodeAt(0));out.push(JSON.stringify(ch)+" gid="+g+" adv="+hmtx.readUInt16BE(g*4)+" lsb="+hmtx.readInt16BE(g*4+2))}
console.log(out.join("\n"));
